<?php
namespace App\Http\Controllers\API;
use App\Http\Controllers\Controller;use App\Http\Resources\{AssetResource,AnnouncementResource};use App\Models\{Asset,Announcement,AuditLog};use Illuminate\Http\Request;use Illuminate\Http\JsonResponse;use Illuminate\Support\Facades\DB;
class PhaseFiveController extends Controller{public function assets(Request $r){return AssetResource::collection(Asset::where('owner_id',$r->user()->id)->latest()->get());}public function storeAsset(Request $r):JsonResponse{$d=$r->validate(['staff_id'=>'nullable|exists:staff,id','name'=>'required|string|max:255','category'=>'required|string|max:100','serial_number'=>'nullable|string|max:100','status'=>'nullable|string|max:30']);$x=Asset::create([...$d,'owner_id'=>$r->user()->id,'assigned_at'=>($d['staff_id']??null)?now()->toDateString():null]);return response()->json(new AssetResource($x),201);}public function announcements(Request $r){return AnnouncementResource::collection(Announcement::where('owner_id',$r->user()->id)->latest()->get());}public function storeAnnouncement(Request $r):JsonResponse{$d=$r->validate(['title'=>'required|string|max:255','body'=>'required|string','status'=>'nullable|in:draft,published']);$x=Announcement::create([...$d,'owner_id'=>$r->user()->id,'published_at'=>($d['status']??'draft')==='published'?now():null]);return response()->json(new AnnouncementResource($x),201);}public function report(Request $r){$id=$r->user()->id;return response()->json(['staff'=>DB::table('staff')->where('owner_id',$id)->count(),'open_jobs'=>DB::table('job_openings')->where('owner_id',$id)->where('status','open')->count(),'pending_expenses'=>DB::table('expenses')->where('owner_id',$id)->where('status','pending')->count(),'pending_leave'=>DB::table('leave_requests')->where('owner_id',$id)->where('status','pending')->count(),'assets'=>DB::table('assets')->where('owner_id',$id)->count()]);}}
